#include <stdio.h>

#define INF 1000000000

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int g[101][101];

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            g[i][j] = INF;
        }
        g[i][i] = 0;
    }

    for (int i = 0; i < M; i++) {
        int A, B, C;
        scanf("%d %d %d", &A, &B, &C);

        if (C < g[A][B]) {
            g[A][B] = C;
            g[B][A] = C;
        }
    }

    int dist[101], visited[101];

    for (int i = 1; i <= N; i++) {
        dist[i] = INF;
        visited[i] = 0;
    }

    dist[1] = 0;

    for (int i = 1; i <= N; i++) {
        int u = -1;
        int best = INF;

        for (int j = 1; j <= N; j++) {
            if (!visited[j] && dist[j] < best) {
                best = dist[j];
                u = j;
            }
        }

        if (u == -1) break;

        visited[u] = 1;

        for (int v = 1; v <= N; v++) {
            if (g[u][v] < INF && dist[u] + g[u][v] < dist[v]) {
                dist[v] = dist[u] + g[u][v];
            }
        }
    }

    printf("%d\n", dist[N]);

    return 0;
}
